{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Lu 25-109, which shares the N-methyl-1,2,3,6-tetrahydropyridine and heteroaromatic core with the query, reached a 1:1 brain:blood ratio in rat microdialysis, directly demonstrating CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In monkey PET studies, the closely related muscarinic agonist CI-979 rapidly entered the brain in high concentrations (5-10% of the intravenous dose), supporting meaningful CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lu 31-126, the deethylated tetrazole analogue, was not detected in brain microdialysate; however, its acidic tetrazole NH is ionized at physiological pH, making this failure a poor model for the lipophilic hexyloxythiadiazole query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "A radiolabeled lipophilic tertiary amine with a long alkyl chain showed a brain-to-blood ratio >20:1 in rats, reinforcing that lipophilic basic amines of this general class can achieve high CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is [11C]xanomeline, a lipophilic basic muscarinic agonist. The closest direct analogue Lu 25-109 shows 1:1 brain:blood partitioning, and PET evidence in monkeys for the related CI-979 shows rapid high brain uptake. The only non-penetrant close analogue is an ionized tetrazole-NH derivative, which is not representative. Overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain exposure measurement for the exact query molecule in the retrieved set; the highest Morgan similarity is moderate (~0.37).",
    "Quantitative unbound brain concentrations or efflux ratio for the exact query are not directly reported in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

